// ============================================================
// SETTINGS — LOCATION values are static; time window is read from Config
// ============================================================
const LOCATION = 'India';           // Search location
const GEO_ID = '102713980';         // India geoId
const LOCATION_FILTER = '105214831'; // Bengaluru, Karnataka f_PP filter

// Read max opening age (in seconds) from the Config tab; default 21600 (6h).
// Supports a header column named maxAgeSeconds, or a vertical label|value row.
function readCfg(name) {
  const target = String(name).trim().toLowerCase();
  try {
    for (const r of $('Get Config').all().map(i => i.json)) {
      for (const k of Object.keys(r)) {
        if (String(k).trim().toLowerCase() === target && r[k] !== '' && r[k] != null) return r[k];
      }
      const vals = Object.values(r);
      for (let i = 0; i < vals.length; i++) {
        if (String(vals[i]).trim().toLowerCase() === target) {
          for (let j = i + 1; j < vals.length; j++) {
            if (vals[j] !== '' && vals[j] != null) return vals[j];
          }
        }
      }
    }
  } catch (e) {}
  return undefined;
}
let TIME_WINDOW_SECONDS = Number(readCfg('maxAgeSeconds'));
if (!Number.isFinite(TIME_WINDOW_SECONDS) || TIME_WINDOW_SECONDS <= 0) TIME_WINDOW_SECONDS = 21600;  // default 6h
console.log('[config] raw Get Config rows: ' + JSON.stringify($('Get Config').all().map(i => i.json)));
console.log('[config] maxAgeSeconds=' + readCfg('maxAgeSeconds') + ' -> TIME_WINDOW_SECONDS=' + TIME_WINDOW_SECONDS + 's');
// ============================================================

const config =  $input.all().map(i => i.json) || [];
// Define keyword templates per bucket
const bucketKeywords = {
  '1': '"software development engineer" OR "SDE" OR "SDE II" OR "SDE 2" OR "SDE-II" OR "software engineer II" OR "Software Engineer-2" OR "software engineer 2" OR "software engineer - II"',
  '2': '"software engineer III" OR "software engineer 3" OR "software developer 3"',
  '3': '"software engineer" OR "software developer" OR "backend engineer" OR "SDE" OR "MTS" OR "member of technical staff"',
  '4': '"software engineer" OR "software developer" OR "backend engineer" OR "SDE" OR "MTS" OR "member of technical staff"'
};

// Group active companies by bucket
const buckets = {};
for (const item of config) {
  const isActive = String(item.Active).toUpperCase() === 'TRUE' || item.Active === true;
  if (!isActive) continue;

  const bucket = String(item.Bucket);
  if (!buckets[bucket]) buckets[bucket] = [];
  buckets[bucket].push(String(item.CompanyID));
}

// ── Publish the TITLE vocabulary from the bucket keywords (single source of
// truth). A scraped job is kept later only if its TITLE contains one of these
// phrases. LinkedIn matches loosely against the whole posting, so this re-
// applies your own search terms to the title. Add variants to a bucket's
// keyword string (e.g. "full stack", "SW engineer") to allow those titles.
const staticData = $getWorkflowStaticData('global');
const phraseSet = new Set();
for (const bucket of Object.keys(buckets)) {
  for (const q of ((bucketKeywords[bucket] || '').match(/"([^"]+)"/g) || [])) {
    phraseSet.add(q.replace(/"/g, '').trim());
  }
}
staticData.titlePhrases = [...phraseSet];
console.log('Title vocabulary (' + staticData.titlePhrases.length + '): ' + staticData.titlePhrases.join(' | '));

// Build LinkedIn search URLs
const urls = [];
for (const [bucket, companyIds] of Object.entries(buckets)) {
  const keywords = bucketKeywords[bucket];
    console.log("bucket: " + bucket);

  if (!keywords || companyIds.length === 0) continue;

  const encodedKeywords = encodeURIComponent(keywords);
  const companyFilter = companyIds.join(',');
  const encodedLocation = encodeURIComponent(LOCATION);

  const url = `https://www.linkedin.com/jobs/search/?keywords=${encodedKeywords}&f_C=${companyFilter}&f_TPR=r${TIME_WINDOW_SECONDS}&location=${encodedLocation}&geoId=${GEO_ID}&f_PP=${LOCATION_FILTER}&sortBy=DD`;


  urls.push({
    url: url,
    bucket: bucket,
    companyCount: companyIds.length
  });
}

console.log(`Built ${urls.length} search URLs for ${Object.keys(buckets).length} active buckets`);

if (urls.length === 0) {
  return [{json: {url: '', bucket: '0', companyCount: 0, noUrls: true}}];
}

return urls.map(u => ({json: u}));

// Reset accumulator at the start of each execution
const staticData = $getWorkflowStaticData('global');
staticData.newJobs = [];
staticData.scoredJobs = [];
return $input.all();

// Store new job data for batch AI scoring later — with EXPERIENCE (years) gating only
const staticData = $getWorkflowStaticData('global');
if (!staticData.newJobs) staticData.newJobs = [];

const jobData = $('Modify Job Attributes').item.json;
const title = String(jobData.title || '');
const description = String(jobData.description || '');

// ── Read experience band [minExp, maxExp] from the Config tab ──
// Supports either a header column named minExp/maxExp, or a vertical
// label|value layout (label in col A, number in col B) like Config!B2..B4.
function readCfg(name) {
  const target = String(name).trim().toLowerCase();
  try {
    for (const r of $('Get Config').all().map(i => i.json)) {
      for (const k of Object.keys(r)) {
        if (String(k).trim().toLowerCase() === target && r[k] !== '' && r[k] != null) return r[k];
      }
      const vals = Object.values(r);
      for (let i = 0; i < vals.length; i++) {
        if (String(vals[i]).trim().toLowerCase() === target) {
          for (let j = i + 1; j < vals.length; j++) {
            if (vals[j] !== '' && vals[j] != null) return vals[j];
          }
        }
      }
    }
  } catch (e) {}
  return undefined;
}
let minExp = Number(readCfg('minExp'));
let maxExp = Number(readCfg('maxExp'));
if (!Number.isFinite(minExp)) minExp = 0;
if (!Number.isFinite(maxExp)) maxExp = Infinity;

// ── TITLE FILTER (search-vocabulary based — no reject list) ──
// Keep a job only if its TITLE contains one of the exact phrases used to build
// the LinkedIn search (bucketKeywords -> staticData.titlePhrases). Change a
// bucket's search string and this filter follows automatically.
const titlePhrases = staticData.titlePhrases || [];
const normStr = (s) => ' ' + String(s).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const normTitle = normStr(title);
const titleOk = titlePhrases.length === 0 ? true : titlePhrases.some(p => normTitle.includes(normStr(p)));
if (!titleOk) {
  console.log('[title-filter] dropped (title not in search vocabulary): ' + title);
  return $input.all();
}

// ── EXPERIENCE FILTER (robust): scan ALL "<n>[+]/<n>-<m> years" mentions,
// ignore company-history prose, and gate on the HIGHEST minimum stated so
// senior roles (e.g. "12+ years") are reliably dropped. Overlap rule vs band.
function parseExp(text) {
  const t = (' ' + text.toLowerCase() + ' ').replace(/[–—]/g, '-').replace(/\s+/g, ' ');
  // Any "<n>[+] [-<m>] year(s)/yr(s)" mention, with an optional lead qualifier.
  const re = /(?:(up to|minimum|min|at least|atleast|over|more than)\s+)?(\d{1,2})\s*(\+)?\s*(?:-|to)?\s*(\d{1,2})?\s*(?:years?|yrs?)\b/g;
  // Skip company-history / tenure prose (not an experience requirement).
  const PROSE_BEFORE = /(for|past|last|over the|since|founded|established|innovating|serving|celebrat|nearly|almost|every)\s*$/;
  const PROSE_AFTER = /^\s*(ago|old|now|running|strong|history|journey|anniversary|of (?:growth|history|innovation|operation|excellence))/;
  const reqs = [];
  let m;
  while ((m = re.exec(t)) !== null) {
    const lead = m[1] || '', n1 = Number(m[2]), plus = !!m[3], n2 = m[4] ? Number(m[4]) : null;
    const before = t.slice(Math.max(0, m.index - 18), m.index);
    const after = t.slice(re.lastIndex, re.lastIndex + 16);
    if (PROSE_BEFORE.test(before) || PROSE_AFTER.test(after)) continue;
    if (/up to/.test(lead)) { reqs.push([0, n2 != null ? n2 : n1]); continue; } // "up to N" = max
    if (n2 != null) reqs.push([Math.min(n1, n2), Math.max(n1, n2)]);            // range "N-M"
    else reqs.push([n1, (plus || lead) ? Infinity : n1]);                      // "N+" / "min N" / bare "N"
  }
  if (reqs.length === 0) return null;
  // Representative requirement = the HIGHEST minimum stated (the senior gate),
  // so a role that anywhere asks for 12+ years is treated as a 12+ role.
  reqs.sort((a, b) => b[0] - a[0]);
  return reqs[0];
}

const jobExp = parseExp(description);
if (jobExp) {
  const [jobMin, jobMax] = jobExp;
  const overlaps = jobMin <= maxExp && jobMax >= minExp; // interval overlap
  if (!overlaps) {
    console.log('[exp-filter] dropped ' + jobMin + '-' + jobMax + ' vs band ' + minExp + '-' + maxExp + ': ' + title);
    return $input.all();
  }
}
// If no experience is stated in the description, the job is kept (per requirement).

// Entry timestamp (IST), recorded when the job first enters the pipeline
const addedAt = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Kolkata' });

staticData.newJobs.push({
  title: jobData.title || '',
  company: jobData.company || '',
  location: jobData.location || '',
  description: jobData.description || '',
  jobid: jobData.jobid || '',
  applyLink: (jobData.applyLink || '').trim(),
  addedAt: addedAt
});

return $input.all();

// BUILD BATCH PROMPT
const staticData = $getWorkflowStaticData('global');
const jobs = staticData.newJobs || [];

if (jobs.length === 0) {
  return [{ json: { hasJobs: false } }];
}

const resume = $('Extract from File').first().json.text || '';
const MAX_DESC = 1500;

const jobSections = jobs.map(job => {
  const desc = (job.description || '').substring(0, MAX_DESC);
  return `---JOB [id: ${job.jobid}]---\nTitle: ${job.title}\nCompany: ${job.company}\nLocation: ${job.location}\nDescription:\n${desc}\n---END JOB---`;
}).join('\n\n');

const prompt = `You are a world-class technical recruiting analyst with deep expertise in software engineering hiring. Your task is to produce rigorous, calibrated match scores between a candidate's resume and multiple job descriptions in a single pass.

## SCORING PHILOSOPHY
- Be brutally honest. A score of 50 means "coin flip".
- Reserve 85+ for near-perfect matches.
- A score below 40 means significant gaps exist.
- Score each job INDEPENDENTLY.

## CANDIDATE RESUME
${resume}

## JOB POSTINGS TO EVALUATE (${jobs.length} job${jobs.length > 1 ? 's' : ''})
Score EACH of the following job postings against the resume above.

${jobSections}

## RESPONSE FORMAT
Respond with ONLY a valid JSON array — no markdown fences, no preamble, no trailing text. I just want the jobid and the score, NOTHING ELSE.

[\n  {"jobid": "<exact id from above>", "score": <total 0-100>},\n  ...\n]\n\nIMPORTANT: You MUST return an entry for EVERY job listed above. Do not skip any.`;

return [{ json: { hasJobs: true, aiPrompt: prompt } }];

// >>> outreach company resolver (generated by outreach/build.mjs, do not edit inside)
// ── util.js ─────────────────────────────────────────────────────────────────
// Shared helpers inlined into every outreach Code node (no require/import:
// n8n Code nodes cannot load local files, so build.mjs concatenates libs).
// All calendar logic is IST (UTC+05:30, no DST) so it never depends on the
// n8n instance timezone.

const IST_OFFSET_MS = 330 * 60 * 1000;
const DAY_MS = 24 * 60 * 60 * 1000;

function pad2(n) { return String(n).padStart(2, '0'); }

// Wall-clock IST parts for an instant.
function istParts(d) {
  const t = new Date((d instanceof Date ? d.getTime() : Number(d)) + IST_OFFSET_MS);
  return { y: t.getUTCFullYear(), m: t.getUTCMonth() + 1, d: t.getUTCDate(),
           hh: t.getUTCHours(), mi: t.getUTCMinutes(), ss: t.getUTCSeconds(), dow: t.getUTCDay() };
}
function istDateStr(d) { const p = istParts(d); return `${p.y}-${pad2(p.m)}-${pad2(p.d)}`; }
function istTsStr(d) { const p = istParts(d); return `${p.y}-${pad2(p.m)}-${pad2(p.d)} ${pad2(p.hh)}:${pad2(p.mi)}:${pad2(p.ss)}`; }
function istMinutesOfDay(d) { const p = istParts(d); return p.hh * 60 + p.mi; }

// IST wall-clock → instant.
function istToDate(y, m, d, hh = 0, mi = 0, ss = 0) {
  return new Date(Date.UTC(y, m - 1, d, hh, mi, ss) - IST_OFFSET_MS);
}

// Accepts what Sheets/Gmail hand back: Date, serial number (days since
// 1899-12-30, IST wall clock), 'YYYY-MM-DD[ HH:mm[:ss]]', ISO with zone,
// 'DD/MM/YYYY[ HH:mm[:ss]]', epoch-ms strings (Gmail internalDate).
function parseTs(v) {
  if (v === null || v === undefined || v === '') return null;
  if (v instanceof Date) return isNaN(v) ? null : v;
  if (typeof v === 'number') {
    if (v > 1e11) return new Date(v);                     // epoch ms
    const ms = Math.round(v * DAY_MS);                     // sheet serial (IST wall clock)
    const base = Date.UTC(1899, 11, 30) + ms;
    return new Date(base - IST_OFFSET_MS);
  }
  const s = String(v).trim();
  if (!s) return null;
  if (/^\d{12,14}$/.test(s)) return new Date(Number(s));
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[ T](\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?)?(Z|[+-]\d{2}:?\d{2})?$/);
  if (m) {
    if (m[7]) { const p = Date.parse(s.replace(' ', 'T')); return isNaN(p) ? null : new Date(p); }
    return istToDate(+m[1], +m[2], +m[3], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
  }
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})(?:,?\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
  if (m) return istToDate(+m[3], +m[2], +m[1], +(m[4] || 0), +(m[5] || 0), +(m[6] || 0));
  const p = Date.parse(s);
  return isNaN(p) ? null : new Date(p);
}

// 'YYYY-MM-DD' (IST) or '' for anything unparseable.
function toIstDate(v) { const d = parseTs(v); return d ? istDateStr(d) : ''; }

function dateStrToUtcNoon(s) { const [y, m, d] = s.split('-').map(Number); return Date.UTC(y, m - 1, d, 12); }
function addCalendarDays(dateStr, n) {
  const t = new Date(dateStrToUtcNoon(dateStr) + n * DAY_MS);
  return `${t.getUTCFullYear()}-${pad2(t.getUTCMonth() + 1)}-${pad2(t.getUTCDate())}`;
}
function daysBetween(a, b) { return Math.round((dateStrToUtcNoon(b) - dateStrToUtcNoon(a)) / DAY_MS); }
function dowOf(dateStr) { return new Date(dateStrToUtcNoon(dateStr)).getUTCDay(); } // 0 = Sun

// sendDays: Set of 0..6, holidays: Set of 'YYYY-MM-DD'
function isBusinessDay(dateStr, sendDays, holidays) {
  return sendDays.has(dowOf(dateStr)) && !holidays.has(dateStr);
}
function addBusinessDays(dateStr, n, sendDays, holidays) {
  let d = dateStr, left = Math.max(0, Math.round(n));
  if (left === 0) return d;
  let guard = 0;
  while (left > 0 && guard++ < 400) {
    d = addCalendarDays(d, 1);
    if (isBusinessDay(d, sendDays, holidays)) left--;
  }
  return d;
}

// Deterministic, alphanumeric-only id (safe for Telegram commands too).
function hashId(prefix, input) {
  const s = String(input || '');
  let h1 = 0x811c9dc5, h2 = 0x01000193 ^ s.length;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ c, 0x5bd1e995) >>> 0;
    h2 = (h2 ^ (h2 >>> 13)) >>> 0;
  }
  return prefix + h1.toString(36).padStart(7, '0') + (h2 % 1296).toString(36).padStart(2, '0');
}

function str(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function normEmail(v) { return str(v).toLowerCase(); }
function normUrl(v) {
  return str(v).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[?#].*$/, '').replace(/\/+$/, '');
}
function isYes(v) { return /^(y|yes|true|1)$/i.test(str(v)); }
function numOrNull(v) {
  if (v === null || v === undefined || str(v) === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
function cmpJobIdDesc(a, b) {
  const x = str(a), y = str(b);
  if (x.length !== y.length) return y.length - x.length;
  return y < x ? -1 : y > x ? 1 : 0;
}

// ── Sheets value grids ──────────────────────────────────────────────────────
// values (2-D array, row 1 = headers) → { headers, rows } where each row has
// `_row` = 1-based sheet row number. Fully empty rows are dropped.
function parseTable(values) {
  const grid = Array.isArray(values) ? values : [];
  const headers = (grid[0] || []).map(h => str(h));
  const rows = [];
  for (let i = 1; i < grid.length; i++) {
    const r = grid[i] || [];
    if (!r.some(c => str(c) !== '')) continue;
    const o = { _row: i + 1 };
    headers.forEach((h, j) => { if (h) o[h] = r[j] === undefined ? '' : r[j]; });
    rows.push(o);
  }
  return { headers, rows, lastRow: grid.length };
}

function colLetter(idx) { // 0-based → A, B, … AA
  let s = '', n = idx + 1;
  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
  return s;
}
function quoteTab(tab) { return `'${String(tab).replace(/'/g, "''")}'`; }

// One ValueRange per field, for values:batchUpdate. Unknown columns are
// skipped (and reported) rather than written somewhere wrong.
function cellWrites(tab, headers, rowNumber, fields, missing) {
  const out = [];
  for (const [k, v] of Object.entries(fields)) {
    const j = headers.indexOf(k);
    if (j < 0) { if (missing) missing.add(`${tab}.${k}`); continue; }
    out.push({ range: `${quoteTab(tab)}!${colLetter(j)}${rowNumber}`, values: [[v === null || v === undefined ? '' : v]] });
  }
  return out;
}
// A whole new row in header order.
function rowWrite(tab, headers, rowNumber, fields) {
  const row = headers.map(h => (fields[h] === undefined || fields[h] === null ? '' : fields[h]));
  return { range: `${quoteTab(tab)}!A${rowNumber}:${colLetter(Math.max(headers.length - 1, 0))}${rowNumber}`, values: [row] };
}

// valueRanges from values:batchGet → { tabName: values }
function rangesByTab(resp) {
  const out = {};
  for (const vr of (resp && resp.valueRanges) || []) {
    const tab = String(vr.range || '').split('!')[0].replace(/^'/, '').replace(/'$/, '').replace(/''/g, "'");
    out[tab] = vr.values || [];
  }
  return out;
}

// Config tab: Setting | Value | Notes (first two non-empty cells per row).
function parseConfig(values) {
  const cfg = {};
  (values || []).forEach((r, i) => {
    if (i === 0 && str(r[0]).toLowerCase() === 'setting') return;
    const k = str(r[0]);
    if (k) cfg[k] = r[1] === undefined ? '' : r[1];
  });
  return cfg;
}
function cfgNum(cfg, key, def) { const n = numOrNull(cfg[key]); return n === null ? def : n; }
function cfgStr(cfg, key, def) { const s = str(cfg[key]); return s === '' ? def : s; }
function cfgList(cfg, key, def) {
  const s = str(cfg[key]);
  return (s === '' ? def : s).split(/[,;\s]+/).map(x => x.trim()).filter(Boolean);
}
function cfgSendDays(cfg) { return new Set(cfgList(cfg, 'sendDays', '1,2,3,4,5').map(Number)); }
function cfgHolidays(cfg) { return new Set(cfgList(cfg, 'holidays', '').map(toIstDate).filter(Boolean)); }
function hhmmToMinutes(s, def) {
  const m = str(s).match(/^(\d{1,2}):(\d{2})$/);
  return m ? (+m[1]) * 60 + (+m[2]) : def;
}

function sheetsUrl(spreadsheetId) { return `https://sheets.googleapis.com/v4/spreadsheets/${spreadsheetId}`; }
// SERIAL_NUMBER keeps typed dates unambiguous (no locale formats); strings we
// write ourselves are RAW so they come back unchanged.
function sheetsBatchGetUrl(spreadsheetId, ranges) {
  return `${sheetsUrl(spreadsheetId)}/values:batchGet?${ranges.map(r => 'ranges=' + encodeURIComponent(r)).join('&')}` +
    '&valueRenderOption=UNFORMATTED_VALUE&dateTimeRenderOption=SERIAL_NUMBER';
}
// Column-wise batchGet (one range per column, all from row 1) → row objects.
function columnsToRows(names, valueRanges) {
  const cols = names.map((n, i) => ((valueRanges || [])[i] && valueRanges[i].values) || []);
  const len = Math.max(0, ...cols.map(c => c.length));
  const rows = [];
  for (let i = 1; i < len; i++) {
    const o = { _row: i + 1 };
    names.forEach((n, j) => { const cell = cols[j][i]; o[n] = cell && cell.length ? cell[0] : ''; });
    if (names.some(n => str(o[n]) !== '')) rows.push(o);
  }
  return rows;
}

// ── company.js ──────────────────────────────────────────────────────────────
// Resolve any spelling of a company (LinkedIn display name, Cowork output,
// legacy sheet text) to the Companies tab's CompanyID. Never guesses: if two
// different IDs match, or nothing matches, it returns ''.

const COMPANY_NOISE = new Set([
  'technologies', 'technology', 'tech', 'group', 'india', 'private', 'pvt', 'limited', 'ltd',
  'inc', 'llc', 'llp', 'corp', 'corporation', 'co', 'company', 'holdings', 'holding', 'advertising',
  'global', 'labs', 'software', 'systems', 'services', 'solutions', 'the', 'and', 'plc', 'gmbh',
]);

function companyTokens(name) {
  return str(name).toLowerCase()
    .replace(/\(.*?\)/g, ' ')          // "(NASDAQ: BKNG)", "(Disney+)"
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim().split(/\s+/).filter(Boolean);
}
function companyKeyExact(name) { return companyTokens(name).join(''); }
function companyKeyLoose(name) {
  const t = companyTokens(name);
  const kept = t.filter(w => !COMPANY_NOISE.has(w));
  return (kept.length ? kept : t).join('');
}

// rows: Companies tab objects with Company, CompanyID, Aliases (';' or ',' separated)
function buildCompanyIndex(rows) {
  const exact = new Map(), loose = new Map(), names = new Map();
  const add = (map, key, id) => {
    if (!key) return;
    if (!map.has(key)) map.set(key, new Set());
    map.get(key).add(id);
  };
  for (const r of rows || []) {
    const id = str(r.CompanyID);
    if (!id) continue;
    if (!names.has(id)) names.set(id, str(r.Company));
    const variants = [str(r.Company), ...str(r.Aliases).split(/[;,|]/)].map(s => s.trim()).filter(Boolean);
    for (const v of variants) { add(exact, companyKeyExact(v), id); add(loose, companyKeyLoose(v), id); }
  }
  return { exact, loose, names };
}

function resolveCompany(index, name) {
  if (!index || !str(name)) return '';
  const pick = (set) => (set && set.size === 1 ? [...set][0] : '');
  const e = index.exact.get(companyKeyExact(name));
  if (e && e.size === 1) return pick(e);
  if (e && e.size > 1) return '';
  return pick(index.loose.get(companyKeyLoose(name)));
}

